<script setup lang="ts">
import { computed, ref } from 'vue'; import type { Attachment, Message, Usage } from '../types'; import { renderMarkdown } from '../utils/markdown'
const props = defineProps<{ message: Message; canRegenerate?: boolean; codeAttachments?: Attachment[]; usage?: Usage }>(); const emit = defineEmits<{ regenerate: []; preview: [attachment: Attachment]; diff: [attachment: Attachment, proposed: string] }>(); const html = computed(() => renderMarkdown(props.message.content)); const copied = ref(false); const copy = async () => { await navigator.clipboard.writeText(props.message.content); copied.value = true; setTimeout(() => copied.value = false, 1400) }
const proposal = computed(() => { const block=/```(?:[\w.+-]+)?\s*\n([\s\S]*?)\n```/.exec(props.message.content); return block?.[1] || '' })
const domain = (url: string) => { try { return new URL(url).hostname } catch { return url } }
const reviewCode = () => { const files=props.codeAttachments || []; if (!proposal.value || !files.length) return; const chosen=files.length===1?files[0]:files.find(f=>f.name===window.prompt(`选择要比较的文件名：\n${files.map(x=>x.name).join('\n')}`,files.at(-1)?.name)); if(chosen)emit('diff',chosen,proposal.value) }
</script>
<template><article :class="['message', message.role]"><div class="avatar">{{ message.role === 'user' ? '你' : '✦' }}</div><div class="message-body"><div class="message-name">{{ message.role === 'user' ? '你' : 'Claude' }}</div><div v-if="message.attachments?.length" class="attachment-list"><template v-for="item in message.attachments" :key="item.id"><button v-if="item.kind === 'document' || item.kind === 'code'" type="button" class="attachment-card attachment-open" :aria-label="`预览 ${item.name}`" @click="emit('preview', item)"><span>▤</span><div><strong>{{ item.name }}</strong><small>点击预览{{ item.kind === 'code' ? '代码' : '文档' }}</small></div></button><div v-else class="attachment-card"><img :src="`data:${item.mime};base64,${item.data}`" :alt="item.name"/><div><strong>{{ item.name }}</strong><small>图片</small></div></div></template></div><div v-if="message.content" class="markdown" v-html="html"/><div v-else-if="message.pending" class="thinking"><i/><i/><i/> 正在思考</div><div v-if="message.sources?.length" class="sources"><a v-for="(source,index) in message.sources" :key="source.url" :href="source.url" target="_blank" rel="noreferrer" class="source-card"><strong>[{{ index+1 }}] {{ source.title }}</strong><small>{{ domain(source.url) }}</small><span>{{ source.snippet }}</span></a></div><div v-if="message.role === 'assistant' && message.content" class="message-tools"><button @click="copy">{{ copied ? '已复制' : '⧉ 复制' }}</button><button v-if="proposal && codeAttachments?.length" @click="reviewCode">查看代码 Diff</button><button v-if="canRegenerate" @click="emit('regenerate')">↻ 重新生成</button></div><small v-if="usage">输入 {{ usage.inputTokens }} · 输出 {{ usage.outputTokens }} · 思考约 {{ usage.thinkingTokens }} Token · {{ (usage.durationMs / 1000).toFixed(1) }}s · ${{ usage.estimatedCost.toFixed(4) }}</small></div></article></template>
